package style

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// Style holds a text styling configuration.
type Style struct {
	Hide       bool
	Bold       bool
	Faint      bool
	Italic     bool
	Underline  bool
	BlinkSlow  bool
	BlinkRapid bool
	Inverse    bool
	Conceal    bool
	CrossOut   bool
	Frame      bool
	Encircle   bool
	Overline   bool
	Foreground *Color
	Background *Color
}

// Color holds an ANSI color.
type Color struct {
	// If named, Code is the ANSI code (30-37 for fg base, 40-47 bg base),
	// and RGB is nil.
	// If RGB color, Code is 0 and RGB has three components.
	Named bool
	// Named base index: 0=black 1=red 2=green 3=yellow 4=blue 5=magenta 6=cyan 7=white
	// Add 60 for light variant.
	Idx int
	RGB []int
}

var colorNames = map[string]int{
	"black":        0,
	"red":          1,
	"green":        2,
	"yellow":       3,
	"blue":         4,
	"magenta":      5,
	"cyan":         6,
	"white":        7,
	"lightBlack":   60,
	"lightRed":     61,
	"lightGreen":   62,
	"lightYellow":  63,
	"lightBlue":    64,
	"lightMagenta": 65,
	"lightCyan":    66,
	"lightWhite":   67,
}

var hexRe = regexp.MustCompile(`^#([0-9a-fA-F]{6})$`)
var rgbRe = regexp.MustCompile(`^rgb\(\s*([^,]+?)\s*,\s*([^,]+?)\s*,\s*([^,]+?)\s*\)$`)

// ParseColor parses a color description like "red", "#rrggbb", or "rgb(r,g,b)".
// Returns nil if the string doesn't parse.
func ParseColor(s string) *Color {
	if idx, ok := colorNames[s]; ok {
		return &Color{Named: true, Idx: idx}
	}
	if m := hexRe.FindStringSubmatch(s); m != nil {
		v, err := strconv.ParseUint(m[1], 16, 32)
		if err == nil {
			return &Color{RGB: []int{int((v >> 16) & 0xff), int((v >> 8) & 0xff), int(v & 0xff)}}
		}
	}
	if m := rgbRe.FindStringSubmatch(s); m != nil {
		r, ok1 := parseColorComponent(m[1])
		g, ok2 := parseColorComponent(m[2])
		b, ok3 := parseColorComponent(m[3])
		if ok1 && ok2 && ok3 {
			return &Color{RGB: []int{r, g, b}}
		}
	}
	return nil
}

func parseColorComponent(s string) (int, bool) {
	s = strings.TrimSpace(s)
	var v uint64
	var err error
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
		v, err = strconv.ParseUint(s[2:], 16, 32)
	} else {
		v, err = strconv.ParseUint(s, 10, 32)
	}
	if err != nil {
		return 0, false
	}
	if v > 255 {
		return 0, false
	}
	return int(v), true
}

// Sequence builds the ANSI escape sequences that start this style.
func (s Style) Sequence() string {
	var b strings.Builder
	if s.Background != nil {
		b.WriteString(colorSeq(s.Background, true))
	}
	if s.Foreground != nil {
		b.WriteString(colorSeq(s.Foreground, false))
	}
	writeAttr(&b, s.Bold, 1)
	writeAttr(&b, s.Faint, 2)
	writeAttr(&b, s.Italic, 3)
	writeAttr(&b, s.Underline, 4)
	writeAttr(&b, s.BlinkSlow, 5)
	writeAttr(&b, s.BlinkRapid, 6)
	writeAttr(&b, s.Inverse, 7)
	writeAttr(&b, s.Conceal, 8)
	writeAttr(&b, s.CrossOut, 9)
	writeAttr(&b, s.Frame, 51)
	writeAttr(&b, s.Encircle, 52)
	writeAttr(&b, s.Overline, 53)
	return b.String()
}

func writeAttr(b *strings.Builder, flag bool, n int) {
	if flag {
		fmt.Fprintf(b, "\x1b[%dm", n)
	}
}

func colorSeq(c *Color, bg bool) string {
	if c.Named {
		base := 30
		if bg {
			base = 40
		}
		// light variants add 60
		return fmt.Sprintf("\x1b[%dm", base+c.Idx)
	}
	prefix := 38
	if bg {
		prefix = 48
	}
	return fmt.Sprintf("\x1b[%d;2;%d;%d;%dm", prefix, c.RGB[0], c.RGB[1], c.RGB[2])
}

// Reset is the ANSI escape sequence to reset styles.
const Reset = "\x1b[0m"

// Apply wraps the given string with the style's escape sequence and a reset.
// Returns the plain string when the style has no visible effect.
func (s Style) Apply(text string) string {
	seq := s.Sequence()
	if seq == "" {
		return text
	}
	return seq + text + Reset
}
EOF
