// LabelType specifies the style of labels in output.
type LabelType int

const (
	LabelLong LabelType = iota
	LabelShort
	LabelNone
)

// Config holds the richgo preferences.
type Config struct {
	LabelType         LabelType
	BuildStyle        style.Style
	StartStyle        style.Style
	PassStyle         style.Style
	FailStyle         style.Style
	SkipStyle         style.Style
	FileStyle         style.Style
	LineStyle         style.Style
	PassPackageStyle  style.Style
	FailPackageStyle  style.Style
	CoverThreshold    int
	CoveredStyle      style.Style
	UncoveredStyle    style.Style
	Removals          []*regexp.Regexp
	LeaveTestPrefix   bool
}

// Default returns the default configuration.
func Default() *Config {
	green := style.ParseColor("green")
	red := style.ParseColor("red")
	yellow := style.ParseColor("yellow")
	lightBlack := style.ParseColor("lightBlack")
	cyan := style.ParseColor("cyan")
	magenta := style.ParseColor("magenta")

	return &Config{
		LabelType:  LabelLong,
		BuildStyle: style.Style{Bold: true, Foreground: yellow},
		StartStyle: style.Style{Foreground: lightBlack},
		PassStyle:  style.Style{Foreground: green},
		FailStyle:  style.Style{Bold: true, Foreground: red},
		SkipStyle:  style.Style{Foreground: lightBlack},
		FileStyle:  style.Style{Foreground: cyan},
		LineStyle:  style.Style{Foreground: magenta},
		PassPackageStyle: style.Style{Hide: true, Foreground: green},
		FailPackageStyle: style.Style{Hide: true, Bold: true, Foreground: red},
		CoverThreshold: 50,
		CoveredStyle:   style.Style{Foreground: green},
		UncoveredStyle: style.Style{Bold: true, Foreground: yellow},
	}
}

// FilePaths returns the list of configuration file paths in priority order.
func FilePaths() []string {
	var dirs []string
	cwd, _ := os.Getwd()
	dirs = append(dirs, cwd)
	if os.Getenv("RICHGO_LOCAL") != "1" {
		if gp := os.Getenv("GOPATH"); gp != "" {
			for _, p := range filepath.SplitList(gp) {
				dirs = append(dirs, p)
			}
		}
		if gr := os.Getenv("GOROOT"); gr != "" {
			dirs = append(dirs, gr)
		} else {
			dirs = append(dirs, "/usr/local/go")
		}
		if home, err := os.UserHomeDir(); err == nil {
			dirs = append(dirs, home)
		}
	}
	var paths []string
	for _, d := range dirs {
		for _, n := range []string{".richstyle", ".richstyle.yaml", ".richstyle.yml"} {
			paths = append(paths, filepath.Join(d, n))
		}
	}
	return paths
}

// Load reads all configuration files (in reverse order so more specific ones override)
// and returns a merged configuration.
func Load() *Config {
	cfg := Default()
	paths := FilePaths()
	// Apply in reverse: least specific first, so more specific ones override.
	for i := len(paths) - 1; i >= 0; i-- {
		p := paths[i]
		f, err := os.Open(p)
		if err != nil {
			continue
		}
		applyYAML(cfg, f)
		f.Close()
	}
	return cfg
}

// applyYAML reads a minimal subset of YAML and applies it to cfg.
func applyYAML(cfg *Config, r io.Reader) error {
	doc, err := parseYAML(r)
	if err != nil {
		return err
	}
	for _, kv := range doc {
		switch kv.key {
		case "labelType":
			switch strings.TrimSpace(kv.value) {
			case "long":
				cfg.LabelType = LabelLong
			case "short":
				cfg.LabelType = LabelShort
			case "none":
				cfg.LabelType = LabelNone
			}
		case "coverThreshold":
			n, err := strconv.Atoi(strings.TrimSpace(kv.value))
			if err == nil {
				cfg.CoverThreshold = n
			}
		case "leaveTestPrefix":
			cfg.LeaveTestPrefix = parseBool(kv.value)
		case "removals":
			// Child list entries
			for _, child := range kv.children {
				if child.key == "-" {
					re, err := regexp.Compile(child.value)
					if err == nil {
						cfg.Removals = append(cfg.Removals, re)
					}
				}
			}
		case "buildStyle":
			applyStyle(&cfg.BuildStyle, kv.children)
		case "startStyle":
			applyStyle(&cfg.StartStyle, kv.children)
		case "passStyle":
			applyStyle(&cfg.PassStyle, kv.children)
		case "failStyle":
			applyStyle(&cfg.FailStyle, kv.children)
		case "skipStyle":
			applyStyle(&cfg.SkipStyle, kv.children)
		case "fileStyle":
			applyStyle(&cfg.FileStyle, kv.children)
		case "lineStyle":
			applyStyle(&cfg.LineStyle, kv.children)
		case "passPackageStyle":
			applyStyle(&cfg.PassPackageStyle, kv.children)
		case "failPackageStyle":
			applyStyle(&cfg.FailPackageStyle, kv.children)
		case "coveredStyle":
			applyStyle(&cfg.CoveredStyle, kv.children)
		case "uncoveredStyle":
			applyStyle(&cfg.UncoveredStyle, kv.children)
		}
	}
	return nil
}

func applyStyle(s *style.Style, children []yamlNode) {
	for _, kv := range children {
		val := kv.value
		switch kv.key {
		case "hide":
			s.Hide = parseBool(val)
		case "bold":
			s.Bold = parseBool(val)
		case "faint":
			s.Faint = parseBool(val)
		case "italic":
			s.Italic = parseBool(val)
		case "underline":
			s.Underline = parseBool(val)
		case "blinkSlow":
			s.BlinkSlow = parseBool(val)
		case "blinkRapid":
			s.BlinkRapid = parseBool(val)
		case "inverse":
			s.Inverse = parseBool(val)
		case "conceal":
			s.Conceal = parseBool(val)
		case "crossOut":
			s.CrossOut = parseBool(val)
		case "frame":
			s.Frame = parseBool(val)
		case "encircle":
			s.Encircle = parseBool(val)
		case "overline":
			s.Overline = parseBool(val)
		case "foreground":
			if c := style.ParseColor(val); c != nil {
				s.Foreground = c
			}
		case "background":
			if c := style.ParseColor(val); c != nil {
				s.Background = c
			}
		}
	}
}

func parseBool(s string) bool {
	return strings.TrimSpace(s) == "true"
}

type yamlNode struct {
	key      string
	value    string
	children []yamlNode
}

// parseYAML parses a minimal indentation-based YAML structure used by richgo
// configuration files. Only key: value pairs, nested maps, and list items
// beginning with "- " are supported. Values may be quoted with "..." to
// include special characters.
func parseYAML(r io.Reader) ([]yamlNode, error) {
	var lines []rawLine
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		t := sc.Text()
		stripped := stripComment(t)
		if strings.TrimSpace(stripped) == "" {
			continue
		}
		indent := 0
		for indent < len(stripped) && stripped[indent] == ' ' {
			indent++
		}
		lines = append(lines, rawLine{indent: indent, text: stripped[indent:]})
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	nodes, _, err := parseBlock(lines, 0, 0)
	return nodes, err
}

type rawLine struct {
	indent int
	text   string
}

func parseBlock(lines []rawLine, start int, indent int) ([]yamlNode, int, error) {
	var nodes []yamlNode
	i := start
	for i < len(lines) {
		ln := lines[i]
		if ln.indent < indent {
			break
		}
		if ln.indent > indent {
			return nil, i, fmt.Errorf("unexpected indent on line %d", i+1)
		}
		if strings.HasPrefix(ln.text, "- ") {
			// list item
			val := strings.TrimSpace(ln.text[2:])
			val = unquote(val)
			nodes = append(nodes, yamlNode{key: "-", value: val})
			i++
			continue
		}
		// Expect "key:" or "key: value"
		colon := strings.IndexByte(ln.text, ':')
		if colon < 0 {
			return nil, i, fmt.Errorf("expected ':' on line %d", i+1)
		}
		key := strings.TrimSpace(ln.text[:colon])
		rest := ""
		if colon+1 < len(ln.text) {
			rest = strings.TrimSpace(ln.text[colon+1:])
		}
		rest = unquote(rest)
		i++
		var children []yamlNode
		if rest == "" {
			// check for children
			if i < len(lines) && lines[i].indent > indent {
				childIndent := lines[i].indent
				var err error
				children, i, err = parseBlock(lines, i, childIndent)
				if err != nil {
					return nil, i, err
				}
			}
		}
		nodes = append(nodes, yamlNode{key: key, value: rest, children: children})
	}
	return nodes, i, nil
}

func stripComment(s string) string {
	inStr := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '"' {
			inStr = !inStr
		} else if c == '#' && !inStr {
			return s[:i]
		}
	}
	return s
}

func unquote(s string) string {
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		inner, err := strconv.Unquote(s)
		if err == nil {
			return inner
		}
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return s[1 : len(s)-1]
	}
	return s
}
