	reCoverLine   = regexp.MustCompile(`^coverage: (\d+\.\d+)% of statements$`)
	rePassStand   = regexp.MustCompile(`^PASS$`)
	reFailStand   = regexp.MustCompile(`^FAIL$`)
	reFileLine    = regexp.MustCompile(`(\S+\.go)(:\d+(?::\d+)?)`)
