// Filter processes lines from src according to cfg and writes the styled
// output to dst. Colorization occurs only when colorize is true.
type Filter struct {
	cfg      *config.Config
	dst      io.Writer
	colorize bool

	lastStyle    *style.Style
	lastCategory category
}

// New creates a new Filter.
func New(cfg *config.Config, dst io.Writer, colorize bool) *Filter {
	return &Filter{cfg: cfg, dst: dst, colorize: colorize}
}

// Run reads lines from src and processes them until EOF.
func (f *Filter) Run(src io.Reader) error {
	// Use a bufio.Scanner with a larger buffer to support long lines.
	sc := bufio.NewScanner(src)
	sc.Buffer(make([]byte, 64*1024), 10*1024*1024)
	for sc.Scan() {
		f.ProcessLine(sc.Text())
	}
	return sc.Err()
}

// ProcessLine handles a single line.
func (f *Filter) ProcessLine(line string) {
	if !f.colorize {
		fmt.Fprintln(f.dst, line)
		return
	}

	cat, content, st, isContinuation := f.classify(line)
	if cat == catNone {
		// continuation
		content = line
	}
	_ = isContinuation

	// Determine effective style.
	effStyle := st
	if cat == catNone {
		effStyle = f.lastStyle
	}

	// Build output label + content.
	out := f.formatLine(cat, content, effStyle)

	// Apply style (except: cover line is special - already contains colorization for percentage and bar; actually no, it uses a single style.)
	// Apply removals
	out = f.applyRemovals(out)

	if out == "" {
		// Suppressed by hide / continuation drop.
		return
	}

	fmt.Fprintln(f.dst, out)

	// Update block state
	if cat != catNone && st != nil && cat != catCover {
		f.lastStyle = st
		f.lastCategory = cat
	}
}

// classify returns the category, the content, style, and whether this is a
// continuation. content is the raw text that will be rendered (possibly
// reformatted). style is the applicable style for the category.
func (f *Filter) classify(line string) (category, string, *style.Style, bool) {
	cfg := f.cfg
	// BUILD
	if reBuildLine.MatchString(line) {
		m := reBuildLine.FindStringSubmatch(line)
		content := m[1] + m[2]
		return catBuild, content, &cfg.BuildStyle, false
	}
	// START
	if cfg.LeaveTestPrefix {
		if m := reRunNoTest.FindStringSubmatch(line); m != nil && strings.HasPrefix(m[1], "Test") {
			name := m[1]
			return catStart, indentForName(strings.TrimPrefix(name, "Test")) + name, &cfg.StartStyle, false
		}
	} else {
		if m := reRun.FindStringSubmatch(line); m != nil {
			name := m[1]
			return catStart, indentForName(name) + name, &cfg.StartStyle, false
		}
	}
	// PASS / FAIL / SKIP for subtests
	if cfg.LeaveTestPrefix {
		if m := rePassLeave.FindStringSubmatch(line); m != nil && strings.HasPrefix(m[2], "Test") {
			name := m[2]
			return catPass, indentForName(strings.TrimPrefix(name, "Test")) + name + m[3], &cfg.PassStyle, false
		}
		if m := reFailLeave.FindStringSubmatch(line); m != nil && strings.HasPrefix(m[2], "Test") {
			name := m[2]
			return catFail, indentForName(strings.TrimPrefix(name, "Test")) + name + m[3], &cfg.FailStyle, false
		}
		if m := reSkipLeave.FindStringSubmatch(line); m != nil && strings.HasPrefix(m[2], "Test") {
			name := m[2]
			return catSkip, indentForName(strings.TrimPrefix(name, "Test")) + name + m[3], &cfg.SkipStyle, false
		}
	} else {
		if m := rePassLabel.FindStringSubmatch(line); m != nil {
			name := m[2]
			return catPass, indentForName(name) + name + m[3], &cfg.PassStyle, false
		}
		if m := reFailLabel.FindStringSubmatch(line); m != nil {
			name := m[2]
			return catFail, indentForName(name) + name + m[3], &cfg.FailStyle, false
		}
		if m := reSkipLabel.FindStringSubmatch(line); m != nil {
			name := m[2]
			return catSkip, indentForName(name) + name + m[3], &cfg.SkipStyle, false
		}
	}
	// PASS / FAIL package lines
	if rePassStand.MatchString(line) {
		return catPassPackage, line, &cfg.PassPackageStyle, false
	}
	if reFailStand.MatchString(line) {
		return catFailPackage, line, &cfg.FailPackageStyle, false
	}
	// ok <pkg> <time> [<coverage>]
	if m := rePassPkg.FindStringSubmatch(line); m != nil {
		pkg := m[1]
		cov := m[2]
		return catPass, pkg + " " + cov, &cfg.PassStyle, false
	}
	// FAIL pkg time or FAIL pkg [build failed]
	if reFailPkg.MatchString(line) || reFailPkgAlt.MatchString(line) {
		// Keep raw content, just strip leading FAIL
		rest := strings.TrimPrefix(line, "FAIL")
		return catFail, rest, &cfg.FailStyle, false
	}
	// ? pkg [no test files]
	if reSkipPkg.MatchString(line) {
		// Leading "?" plus spaces/tab, replace with label only, keep rest including tab.
		idx := skipPrefixLen(line)
		rest := line[idx:]
		return catSkip, rest, &cfg.SkipStyle, false
	}
