	if m := reCoverLine.FindStringSubmatch(line); m != nil {
		pctStr := m[1]
		pct, _ := strconv.ParseFloat(pctStr, 64)
		var st *style.Style
		if pct >= float64(f.cfg.CoverThreshold) {
			st = &f.cfg.CoveredStyle
		} else {
			st = &f.cfg.UncoveredStyle
		}
		bar := buildBar(pct)
		content := fmt.Sprintf("%s%% %s", pctStr, bar)
		return catCover, content, st, false
	}
	return catNone, line, nil, true
}

// skipPrefixLen returns the length of the leading "? \t" prefix in a skipPkg line.
func skipPrefixLen(line string) int {
	// Expect "?" then one or more spaces/tabs then package... We want to strip
	// up through the whitespace immediately following the "?".
	i := 0
	if i < len(line) && line[i] == '?' {
		i++
	}
	for i < len(line) && (line[i] == ' ' || line[i] == '\t') {
		i++
	}
	return i
}

func buildBar(pct float64) string {
	n := int(pct / 10)
	if n > 10 {
		n = 10
	}
	if n < 0 {
		n = 0
	}
	return "[" + strings.Repeat("#", n) + strings.Repeat("_", 10-n) + "]"
}

func indentForName(name string) string {
	depth := strings.Count(name, "/")
	return strings.Repeat("  ", depth)
}

// formatLine builds the styled line for the given category.
func (f *Filter) formatLine(cat category, content string, st *style.Style) string {
	// If category style says hide, return "".
	if st != nil && st.Hide {
		switch cat {
		case catPassPackage, catFailPackage:
			return ""
		}
	}
	var label string
	// Determine label prefix.
	switch f.cfg.LabelType {
	case config.LabelLong:
		label = longLabel(cat)
	case config.LabelShort:
		label = shortLabel(cat)
	case config.LabelNone:
		label = ""
	}
	// Build content with file:line colorization.
	rendered := f.colorizeFileLine(content, st)
	// Combine: label + content.
	line := label + rendered
	if st != nil {
		line = st.Sequence() + line + style.Reset
	}
	return line
}

func longLabel(cat category) string {
	switch cat {
	case catBuild:
		return "BUILD| "
	case catStart:
		return "START| "
	case catPass:
		return "PASS | "
	case catFail:
		return "FAIL | "
	case catSkip:
		return "SKIP | "
	case catCover:
		return "COVER| "
	case catPassPackage:
		return ""
	case catFailPackage:
		return ""
	case catNone:
		return "     | "
	}
	return ""
}

func shortLabel(cat category) string {
	switch cat {
	case catBuild:
		return "!! "
	case catStart:
		return ">  "
	case catPass:
		return "o  "
	case catFail:
		return "x  "
	case catSkip:
		return "-  "
	case catCover:
		return "%  "
	case catPassPackage:
		return ""
	case catFailPackage:
		return ""
	case catNone:
		return "   "
	}
	return ""
}

// colorizeFileLine injects file/line styles into content. The outer style `st`
// is restored after each file:line match. If st is nil (or the output is not
// colorized), only the file and line styles are injected (without an outer
// reset afterward; we rely on the caller to wrap with the outer style).
func (f *Filter) colorizeFileLine(content string, outer *style.Style) string {
	fileSeq := f.cfg.FileStyle.Sequence()
	lineSeq := f.cfg.LineStyle.Sequence()
	outerSeq := ""
	if outer != nil {
		outerSeq = outer.Sequence()
	}
	return reFileLine.ReplaceAllStringFunc(content, func(match string) string {
		m := reFileLine.FindStringSubmatch(match)
		return fileSeq + m[1] + style.Reset + lineSeq + m[2] + style.Reset + outerSeq
	})
}

// applyRemovals applies all removal regexps to the line. Lines that become
// empty (or match the "empty continuation" heuristic) are dropped.
func (f *Filter) applyRemovals(line string) string {
	for _, re := range f.cfg.Removals {
		line = re.ReplaceAllString(line, "")
	}
	// Drop line if, after stripping ANSI sequences, the continuation content is empty.
	// Specifically: a continuation line like "     | " that has no content after the pipe
	// should be dropped.
	if isEmptyContinuation(line) {
		return ""
	}
	return line
}

var ansiRe = regexp.MustCompile("\x1b\\[[0-9;]*m")

func isEmptyContinuation(line string) bool {
	stripped := ansiRe.ReplaceAllString(line, "")
	// If everything is whitespace or empty, drop the line.
	if strings.TrimSpace(stripped) == "" {
		return true
	}
	// Check continuation-only patterns: "     | " (long) or "   " (short).
	// If the remaining line is exactly the continuation prefix, drop it.
	if stripped == "     | " || stripped == "   " {
		return true
	}
	// If continuation prefix is followed only by whitespace, drop it.
	if strings.HasPrefix(stripped, "     | ") && strings.TrimSpace(stripped[len("     | "):]) == "" {
		return true
	}
	return false
}
