	reRunNoTest   = regexp.MustCompile(`^=== RUN {3}(Test.*)$`)
	rePassLabel   = regexp.MustCompile(`^(\s*)--- PASS: Test(\S*)(.*)$`)
	reFailLabel   = regexp.MustCompile(`^(\s*)--- FAIL: Test(\S*)(.*)$`)
	reSkipLabel   = regexp.MustCompile(`^(\s*)--- SKIP: Test(\S*)(.*)$`)
	rePassLeave   = regexp.MustCompile(`^(\s*)--- PASS: (Test\S*)(.*)$`)
	reFailLeave   = regexp.MustCompile(`^(\s*)--- FAIL: (Test\S*)(.*)$`)
	reSkipLeave   = regexp.MustCompile(`^(\s*)--- SKIP: (Test\S*)(.*)$`)
	rePassPkg     = regexp.MustCompile(`^ok[ \t]+(\S+)[ \t]+\S+(?:[ \t]+(coverage: \d+\.\d+% of statements))?$`)
	reFailPkg     = regexp.MustCompile(`^FAIL\t\S+\t(\d+(?:\.\d+)?s|\[[^\]]+\])$`)
	reFailPkgAlt  = regexp.MustCompile(`^FAIL\t\S+ \[[^\]]+\]$`)
	reSkipPkg     = regexp.MustCompile(`^\?[ \t]+\S+[ \t]+\[[^\]]+\]$`)
	reBuildLine   = regexp.MustCompile(`^# (\S+)( \[\S+\])?$`)
	reCoverLine   = regexp.MustCompile(`^coverage: (\d+\.\d+)% of statements$`)
	rePassStand   = regexp.MustCompile(`^PASS$`)
	reFailStand   = regexp.MustCompile(`^FAIL$`)
	reFileLine    = regexp.MustCompile(`(\S+\.go)(:\d+(?::\d+)?)`)
)

// Filter processes lines from src according to cfg and writes the styled
// output to dst. Colorization occurs only when colorize is true.
type Filter struct {
	cfg      *config.Config
	dst      io.Writer
	colorize bool

	lastStyle    *style.Style
}

// New creates a new Filter.
func New(cfg *config.Config, dst io.Writer, colorize bool) *Filter {
	return &Filter{cfg: cfg, dst: dst, colorize: colorize}
}

