			name := m[2]
			return catPass, indentForName(name) + name + m[3], &cfg.PassStyle
		}
		if m := reFailLabel.FindStringSubmatch(line); m != nil {
			name := m[2]
			return catFail, indentForName(name) + name + m[3], &cfg.FailStyle
		}
		if m := reSkipLabel.FindStringSubmatch(line); m != nil {
			name := m[2]
			return catSkip, indentForName(name) + name + m[3], &cfg.SkipStyle
		}
	}
	// Standalone PASS / FAIL.
	if rePassStand.MatchString(line) {
		return catPassPackage, line, &cfg.PassPackageStyle
	}
	if reFailStand.MatchString(line) {
		return catFailPackage, line, &cfg.FailPackageStyle
	}
	// Package ok line (pass style).
	if m := rePassPkg.FindStringSubmatch(line); m != nil {
		pkg := m[1]
		cov := m[2]
		return catPass, pkg + " " + cov, &cfg.PassStyle
	}
