// skipPrefixLen returns the length of the leading "? \t" prefix in a skipPkg
// line.
func skipPrefixLen(line string) int {
	i := 0
	if i < len(line) && line[i] == '?' {
		i++
	}
	for i < len(line) && (line[i] == ' ' || line[i] == '\t') {
		i++
	}
	return i
}

func buildBar(pct float64) string {
	n := int(pct / 10)
	if n > 10 {
		n = 10
	}
	if n < 0 {
		n = 0
	}
	return "[" + strings.Repeat("#", n) + strings.Repeat("_", 10-n) + "]"
}

func indentForName(name string) string {
	depth := strings.Count(name, "/")
	return strings.Repeat("  ", depth)
}

func continuationPrefix(lt config.LabelType) string {
	switch lt {
	case config.LabelLong:
		return "     | "
	case config.LabelShort:
		return "   "
	}
	return ""
}

func longLabel(cat category) string {
	switch cat {
	case catBuild:
		return "BUILD| "
	case catStart:
		return "START| "
	case catPass:
		return "PASS | "
	case catFail:
		return "FAIL | "
	case catSkip:
		return "SKIP | "
	case catCover:
		return "COVER| "
	case catPassPackage, catFailPackage:
		return ""
	}
	return ""
}

func shortLabel(cat category) string {
	switch cat {
	case catBuild:
		return "!! "
	case catStart:
		return ">  "
	case catPass:
		return "o  "
	case catFail:
		return "x  "
	case catSkip:
		return "-  "
	case catCover:
		return "%  "
	case catPassPackage, catFailPackage:
		return ""
	}
	return ""
}

// colorizeFileLine injects file/line styles into content. The outer style is
// restored after each file:line match.
func (f *Filter) colorizeFileLine(content string, outer *style.Style) string {
	fileSeq := f.cfg.FileStyle.Sequence()
	lineSeq := f.cfg.LineStyle.Sequence()
	var outerSeq string
	if outer != nil {
		outerSeq = outer.Sequence()
	}
	return reFileLine.ReplaceAllStringFunc(content, func(match string) string {
		m := reFileLine.FindStringSubmatch(match)
		return fileSeq + m[1] + style.Reset + lineSeq + m[2] + style.Reset + outerSeq
	})
}

// applyRemovals applies all configured removal regexps to the line.
func (f *Filter) applyRemovals(line string) string {
	for _, re := range f.cfg.Removals {
		line = re.ReplaceAllString(line, "")
	}
	return line
}

var ansiRe = regexp.MustCompile("\x1b\\[[0-9;]*m")

// isEmptyContinuation reports whether the given styled line consists solely
// of the continuation prefix (possibly with trailing/leading whitespace).
func (f *Filter) isEmptyContinuation(line string) bool {
	stripped := ansiRe.ReplaceAllString(line, "")
	prefix := continuationPrefix(f.cfg.LabelType)
	if prefix == "" {
		// labelType: none – drop when result is pure whitespace/empty.
		return strings.TrimSpace(stripped) == ""
	}
	// Drop when stripped (right-trimmed) equals the continuation prefix
	// (also right-trimmed).
	rt := strings.TrimRight(stripped, " \t")
	rp := strings.TrimRight(prefix, " \t")
	return rt == rp
}
